namespace ThisIsMyPC.App.ViewModels;

/// <summary>Module-specific lessons. No claims of live inspection or automatic enforcement.</summary>
public static class SetupLessons
{
    public static SetupLessonViewModel For(string name, string description) => name switch
    {
        "Windows Annoyances" => new(name, "Stop the interruptions", "Control Windows suggestions, promotional surfaces, and optional experiences.",
            "Windows can use Start, Settings, and the lock screen to suggest products and features. These prompts are not system errors.",
            "The pack reduces promotions and optional experiences. Review each recommendation, especially features you already use.",
            "Return here when a new prompt appears. Similar-looking prompts can have different controls; turning off one does not disable all promotions."),
        "Privacy & Telemetry" => new(name, "Choose what you share", "Review diagnostic data, activity tracking, and personalization controls.",
            "Windows distinguishes required diagnostic data from optional data. Turning off optional collection does not mean the PC sends no data.",
            "The pack limits optional data and tracking through supported controls. Edition and policy restrictions can make some choices unavailable.",
            "Review permissions for newly installed apps. A Windows setting does not control every app's own data collection."),
        "Windows Update" => new(name, "Keep updates on your terms", "Review update behavior, scheduling, and supported update policies.",
            "Updates deliver fixes but can also change features and defaults. Disabling updates can leave known vulnerabilities unfixed.",
            "Review your update schedule in this module. The cleanup pack does not disable updates or pin your Windows version.",
            "After major updates, check the settings you care about. Investigate a change before assuming an update caused it."),
        "Software" => new(name, "Keep the apps you need", "Review installed software, Windows apps, available updates, and the app catalog.",
            "A bundled app is not necessarily essential. It is also not necessarily unwanted: people use different tools.",
            "The pack preselects a small list of optional Windows app removals. Keep apps you use; removals apply to all users.",
            "Save app data before removal. Reinstall through Software or the Store when available. Removing an app is not a reversible setting."),
        "Security" => new(name, "Know what protects you", "Inspect sign-in, antivirus, app protection, and security notification settings.",
            "Security services can use resources because they scan and protect the PC. Resource use alone does not make them bloat.",
            "Use this module to understand protections. The pack does not turn off Defender, the firewall, or sign-in protections.",
            "Investigate security warnings instead of hiding them to make the PC look clean. Some controls can be protected by policy."),
        "Network & Firewall" => new(name, "Understand your connections", "Review network adapters, DNS settings, firewall profiles, and available rule information.",
            "Apps and Windows services use the network for different reasons. Blocking traffic can also break sign-in, updates, or shared devices.",
            "Inspect your connections here. The pack does not replace DNS, disable adapters, or switch off the firewall.",
            "Review network changes when installing VPN or security software. Record working settings before making connectivity changes."),
        "Startup & Services" => new(name, "Decide what starts with Windows", "Inspect sign-in startup entries, services, and scheduled tasks.",
            "Installed apps can add background components. Some launch an app sooner; others provide updates, hardware support, or essential Windows functions.",
            "Review startup entries individually. Disabling startup does not uninstall the app. The pack does not blanket-disable services.",
            "Return after installing software or noticing slower sign-in. Check the publisher and purpose before disabling an unfamiliar entry."),
        "Explorer" => new(name, "Make files easier to manage", "Customize File Explorer and supported taskbar behavior.",
            "Windows defaults balance discovery and simplicity. Hidden file extensions, for example, can make different file types harder to distinguish.",
            "Review the pack's Explorer choices and keep your preferred layout. More customization remains available inside this module.",
            "Some changes may require an Explorer restart. Revisit Explorer when a Windows update changes the available interface."),
        "Context Menus" => new(name, "Clean up right-click menus", "Inspect menu entries and extensions added by Windows and installed software.",
            "Apps can add menu entries during installation. Useful shortcuts can accumulate into a crowded menu.",
            "Choose entries based on what you use. The pack does not disable unknown menu handlers on your behalf.",
            "Check this module when an app adds unwanted entries. Keep entries needed for file operations or tools you use."),
        "Environment" => new(name, "Understand app search paths", "Review environment variables used by Windows and applications.",
            "Installers can add folders to PATH so commands can find their programs. Old or conflicting entries can cause confusing behavior.",
            "Change variables only when you understand their purpose. The pack leaves these values alone.",
            "After uninstalling development tools, inspect leftover entries before removing them. Other software may still depend on a shared folder."),
        "Power Plans" => new(name, "Balance power and responsiveness", "Review power plans, sleep behavior, and supported power settings.",
            "Power settings trade energy use, heat, and responsiveness. The highest performance setting is not automatically the best desktop setting.",
            "Choose sleep and performance behavior for your use. The pack does not disable sleep or force a power plan.",
            "Check your plan after installing hardware utilities. Avoid letting multiple utilities repeatedly change the same power settings."),
        "Display" => new(name, "Set up your screens", "Review connected displays and their supported controls.",
            "Monitor firmware, graphics drivers, and Windows each control parts of the display experience. Available controls differ by device.",
            "Use supported controls to suit your workspace. The cleanup pack does not change display modes or brightness.",
            "Recheck display settings after replacing a monitor or updating graphics drivers. Unsupported controls are not evidence of a broken monitor."),
        "System Control" => new(name, "Understand manufacturer controls", "Find supported manufacturer controls and companion software.",
            "Manufacturer utilities can provide essential device functions as well as optional extras. Removing every manufacturer app can remove useful controls.",
            "Read the compatibility information before choosing a companion. Many System Control features target laptops and may be unavailable on this desktop.",
            "Keep a way to receive firmware updates. The pack does not remove manufacturer utilities or change device-specific controls."),
        "Lighting" => new(name, "Take control of lighting", "Inspect supported lighting devices and choose their lighting behavior.",
            "Multiple lighting apps can compete for the same device. Detection does not guarantee every effect or controller is supported.",
            "Choose one controller for each device. The cleanup pack does not remove lighting software or alter device colors.",
            "If a device disappears, check whether another controller is running. Revisit compatibility information after hardware changes."),
        "Cooling" => new(name, "Keep cooling deliberate", "Review supported cooling controls and FanControl integration.",
            "Fans protect hardware from heat. Quieter settings can raise temperatures, and curves depend on the actual fans and sensors in this PC.",
            "Identify and calibrate supported fans before changing curves. The pack does not change cooling behavior.",
            "Monitor temperatures after changes. Do not copy another PC's curve without checking sensor mapping and cooling capacity."),
        "Monitoring" => new(name, "Measure before you change", "Inspect available hardware readings such as load, temperature, and fan speed.",
            "A busy process or a brief temperature spike does not by itself prove bloat. Workload and sensor support affect what you see.",
            "Use monitoring to compare behavior during the same task. The pack does not change sensors or promise a performance increase.",
            "Compare readings over time. Missing sensors mean unavailable readings, not zero temperature or zero activity."),
        _ => new(name, name, description, "Available controls depend on this PC and its installed software.",
            "Open this module to inspect its controls before changing them.", "Review changes before applying. Check whether a control supports undo."),
    };
}
